-- Verify migration 0072 (application party removal). Read-only. Expect every row PASS.
SELECT 'application_party has relationship_to_primary, removed_at and removed_by' AS check,
       CASE WHEN EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'application_party' AND column_name = 'relationship_to_primary') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'application_party' AND column_name = 'removed_at') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'application_party' AND column_name = 'removed_by') THEN 'PASS' ELSE 'FAIL' END AS result
UNION ALL SELECT 'rows may only be marked removed (remove-only trigger replaces append-only)',
       CASE WHEN EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = to_regclass('app.application_party') AND tgname = 'application_party_remove_only' AND NOT tgisinternal) AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = to_regclass('app.application_party') AND tgname = 'application_party_append_only' AND NOT tgisinternal) THEN 'PASS' ELSE 'FAIL' END
UNION ALL SELECT 'a customer is unique among the parties still on the application',
       CASE WHEN to_regclass('app.application_party_active_customer_uq') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('app.application_party') AND conname = 'application_party_application_id_customer_id_key') THEN 'PASS' ELSE 'FAIL' END
UNION ALL SELECT 'dsa_app may set removed_at and removed_by only',
       CASE WHEN coalesce((SELECT has_column_privilege('dsa_app', a.attrelid, a.attnum, 'UPDATE') FROM pg_attribute a WHERE a.attrelid = to_regclass('app.application_party') AND a.attname = 'removed_at' AND NOT a.attisdropped), false) AND coalesce((SELECT has_column_privilege('dsa_app', a.attrelid, a.attnum, 'UPDATE') FROM pg_attribute a WHERE a.attrelid = to_regclass('app.application_party') AND a.attname = 'removed_by' AND NOT a.attisdropped), false) AND NOT coalesce((SELECT has_column_privilege('dsa_app', a.attrelid, a.attnum, 'UPDATE') FROM pg_attribute a WHERE a.attrelid = to_regclass('app.application_party') AND a.attname = 'customer_id' AND NOT a.attisdropped), false) THEN 'PASS' ELSE 'FAIL' END;
